    xref_issue_nr = self._get_xref_issues(stream, startxref)
    if xref_issue_nr != 0:
        if self.strict and xref_issue_nr:
            raise PdfReadError("Broken xref table")
        logger_warning(
            "incorrect startxref pointer(%(xref_issue_nr)d)",
            source=__name__,
            xref_issue_nr=xref_issue_nr,
        )

